local PlaneIronMaker = {}
local PRODUCTS = {
    iron_plane_iron = { name = "Železna železa za glodalnik", ironCost = 4, woodCost = 2, leatherCost = 1, time = 5, cost = 180, prestige = 4, happiness = 2, description = "Železna železa za gladko glodalno površino." },
    bronze_plane_iron = { name = "Bronasta železa za glodalnik", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 435, prestige = 6, happiness = 3, description = "Bronasta železa za natančno glodanje." },
    silver_plane_iron = { name = "Srebrna železa za glodalnik", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1050, prestige = 11, happiness = 4, description = "Srebrna železa za plemiške mizarje." },
    gilded_plane_iron = { name = "Pozlačena železa za glodalnik", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2250, prestige = 20, happiness = 5, description = "Pozlačena železa za dvorne mizarje." },
    jewel_set_plane_iron = { name = "Draguljasta železa za glodalnik", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4850, prestige = 36, happiness = 7, description = "Draguljasta železa za kraljevske mizarje." },
    royal_sovereign_plane_iron = { name = "Kraljevski suverena železa za glodalnik", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10400, prestige = 68, happiness = 13, description = "Suverena železa z biseri za krono." },
}
local BUILDINGS = {
    planeiron_workshop = { name = "Gladilna delavnica", cost = { gold = 360, wood = 185, stone = 140, iron = 10 }, upkeep = 7, qualityBonus = 5 },
    planeiron_house = { name = "Gladilna hiša", cost = { gold = 1255, wood = 370, stone = 280, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_planeiron_atelier = { name = "Mojstrski gladilni atelje", cost = { gold = 3140, wood = 430, stone = 535, silver = 37, gold = 7 }, upkeep = 74, qualityBonus = 30 },
    sovereign_planeiron_palace = { name = "Suverena gladilna palača", cost = { gold = 13300, wood = 655, stone = 845, gold = 85, jewel = 19 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
PlaneIronMaker.ironStock = 16; PlaneIronMaker.bronzeStock = 12; PlaneIronMaker.woodStock = 12; PlaneIronMaker.leatherStock = 8; PlaneIronMaker.silverStock = 8; PlaneIronMaker.goldStock = 6; PlaneIronMaker.jewelStock = 4; PlaneIronMaker.pearlStock = 4
PlaneIronMaker.productStock = {}; PlaneIronMaker.buildings = {}; PlaneIronMaker.maker = nil; PlaneIronMaker.activeMaking = {}; PlaneIronMaker.totalProducts = 0; PlaneIronMaker.dayTimer = 0
function PlaneIronMaker.init() PlaneIronMaker.ironStock=16; PlaneIronMaker.bronzeStock=12; PlaneIronMaker.woodStock=12; PlaneIronMaker.leatherStock=8; PlaneIronMaker.silverStock=8; PlaneIronMaker.goldStock=6; PlaneIronMaker.jewelStock=4; PlaneIronMaker.pearlStock=4; PlaneIronMaker.productStock={}; PlaneIronMaker.buildings={}; PlaneIronMaker.maker=nil; PlaneIronMaker.activeMaking={}; PlaneIronMaker.totalProducts=0; PlaneIronMaker.dayTimer=0; print("[PlaneIronMaker] Royal Plane Iron Maker System initialized (6 products, 4 buildings)") end
function PlaneIronMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlaneIronMaker.maker={name=n or ("Gladar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gladar najet: %s (spretnost: %d)",PlaneIronMaker.maker.name,s),"success") end; return true end
function PlaneIronMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlaneIronMaker.build(id) local ok,e=PlaneIronMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlaneIronMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlaneIronMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlaneIronMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlaneIronMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlaneIronMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlaneIronMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlaneIronMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlaneIronMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlaneIronMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlaneIronMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlaneIronMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlaneIronMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlaneIronMaker.buildings==0 then return false,"Potrebna gladilna delavnica" end; if not PlaneIronMaker.maker then return false,"Potreben gladar" end; return true end
function PlaneIronMaker.make(pt,qty) qty=qty or 1; local ok,e=PlaneIronMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlaneIronMaker.ironStock=PlaneIronMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlaneIronMaker.bronzeStock=PlaneIronMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlaneIronMaker.woodStock=PlaneIronMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlaneIronMaker.leatherStock=PlaneIronMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlaneIronMaker.silverStock=PlaneIronMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlaneIronMaker.goldStock=PlaneIronMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlaneIronMaker.jewelStock=PlaneIronMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlaneIronMaker.pearlStock=PlaneIronMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlaneIronMaker.maker then t=math.max(1,t-math.floor(PlaneIronMaker.maker.skill/13)) end; table.insert(PlaneIronMaker.activeMaking,{id="planeiron_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlaneIronMaker.completeMaking(m) local q=1.0+(PlaneIronMaker.getQualityBonus()/100); if PlaneIronMaker.maker then q=q+(PlaneIronMaker.maker.skill/140) end; q=math.min(2.5,q); PlaneIronMaker.productStock[m.productType]=(PlaneIronMaker.productStock[m.productType] or 0)+m.quantity; PlaneIronMaker.totalProducts=PlaneIronMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlaneIronMaker.maker then PlaneIronMaker.maker.itemsMade=PlaneIronMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlaneIronMaker.maker.skill=math.min(100,PlaneIronMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Železa izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"planeiron.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlaneIronMaker.update(dt) if not _G.state then return end; PlaneIronMaker.dayTimer=PlaneIronMaker.dayTimer+dt; if PlaneIronMaker.dayTimer>=30 then PlaneIronMaker.dayTimer=0; for i=#PlaneIronMaker.activeMaking,1,-1 do local m=PlaneIronMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlaneIronMaker.completeMaking(m); table.remove(PlaneIronMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlaneIronMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlaneIronMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlaneIronMaker.getStats() return {ironStock=PlaneIronMaker.ironStock,bronzeStock=PlaneIronMaker.bronzeStock,woodStock=PlaneIronMaker.woodStock,leatherStock=PlaneIronMaker.leatherStock,silverStock=PlaneIronMaker.silverStock,goldStock=PlaneIronMaker.goldStock,jewelStock=PlaneIronMaker.jewelStock,pearlStock=PlaneIronMaker.pearlStock,productStock=PlaneIronMaker.productStock,numBuildings=#PlaneIronMaker.buildings,hasMaker=PlaneIronMaker.maker~=nil,makerName=PlaneIronMaker.maker and PlaneIronMaker.maker.name or "—",makerSkill=PlaneIronMaker.maker and PlaneIronMaker.maker.skill or 0,activeMaking=#PlaneIronMaker.activeMaking,totalProducts=PlaneIronMaker.totalProducts} end
return PlaneIronMaker
